html:
{%- set doc = frappe.get_doc(doc.doctype, doc.name) -%}
{%- set company = frappe.get_doc("Company", doc.company) -%}

{#-- International flag: any non-INR currency = international --#}
{%- set is_international = (doc.currency and doc.currency != "INR") -%}
{%- set display_currency = doc.currency or "INR" -%}

{#-- Sales person: prefer custom_sales_person (locked at creation time),
     then fall back to sales_team resolution, then doc owner --#}
{%- set sales_person_name = doc.get("custom_sales_person") or "" -%}
{%- if not sales_person_name -%}
    {%- if doc.sales_team and doc.sales_team[0].sales_person -%}
        {%- set sp_employee = frappe.db.get_value("Sales Person", doc.sales_team[0].sales_person, "employee_name") -%}
        {%- set sales_person_name = sp_employee or doc.sales_team[0].sales_person -%}
    {%- endif -%}
{%- endif -%}
{%- if not sales_person_name -%}
    {%- set creator_full_name = frappe.db.get_value("User", doc.owner, "full_name") -%}
    {%- set sales_person_name = creator_full_name or doc.owner -%}
{%- endif -%}
{%- if not sales_person_name -%}{%- set sales_person_name = "—" -%}{%- endif -%}

{#-- Dynamic GSTIN & Warehouse info based on custom_location --#}
{%- set warehouse_map = {
    "MAHARASHTRA": "MAHARASHTRA - IB",
    "GUJARAT":     "GUJARAT - IB",
    "CHENNAI":     "CHENNAI - IB"
} -%}
{%- set location_key = (doc.custom_location or "") | upper | trim -%}
{%- set wh_name = warehouse_map.get(location_key) -%}
{%- set company_gstin = company.get("gstin") or "24AAECI3431Q1ZE" -%}
{%- if wh_name -%}
    {%- set wh_doc = frappe.get_doc("Warehouse", wh_name) -%}
    {%- set display_gstin = wh_doc.get("custom_gstin") or company_gstin -%}
    {%- set wh_abbr = wh_doc.get("address_line_1") or wh_name -%}
    {%- set wh_email = wh_doc.get("email_id") or "—" -%}
    {%- set wh_phone = wh_doc.get("custom_phone") or "—" -%}
{%- else -%}
    {%- set display_gstin = company_gstin -%}
    {%- set wh_abbr = "—" -%}
    {%- set wh_email = "—" -%}
    {%- set wh_phone = "—" -%}
{%- endif -%}

{#-- Address fallback chain --#}
{%- set address_html = frappe.db.get_value("Customer", doc.party_name or doc.customer, "custom_billing") or "—" -%}

{#-- Customer country for international docs --#}
{%- set customer_country = frappe.db.get_value("Customer", doc.party_name or doc.customer, "custom_country") or "" -%}

{#-- Contact mobile --#}
{%- set contact_display = "" -%}
{%- if doc.get("contact_person") -%}
    {%- set contact_mobile = frappe.db.get_value("Customer", doc.custom_primary_contact_person, "custom_primary_contact_person") -%}
    {%- set contact_display = contact_mobile -%}
{%- else -%}
    {%- set contact_display = doc.get("contact_display") or "" -%}
{%- endif -%}

{#-- Calculate total tax amount for proportional distribution --#}
{%- set total_tax_amount = 0 -%}
{%- if doc.taxes -%}
    {%- for tax in doc.taxes -%}
        {%- set total_tax_amount = total_tax_amount + (tax.tax_amount or 0) -%}
    {%- endfor -%}
{%- endif -%}

{#-- Float display: integer if whole, else 2dp --#}
{%- macro fmt_num(val) -%}
    {%- set v = val | float -%}
    {%- if v == v | int -%}{{ v | int }}{%- else -%}{{ "%.2f" | format(v) }}{%- endif -%}
{%- endmacro -%}

{#-- Qty display: integer if whole, else full precision (no rounding) --#}
{%- macro fmt_qty(val) -%}
    {%- set v = val | float -%}
    {%- if v == v | int -%}{{ v | int }}{%- else -%}{{ "%.10g" | format(v) }}{%- endif -%}
{%- endmacro -%}

{#-- Parse liner from custom_specifications --#}
{%- macro parse_liner(item) -%}
    {%- set desc = item.get("custom_specifications") or item.get("description") or "" -%}
    {%- if desc and " | " in desc -%}
        {%- set right = desc.split(" | ")[1] -%}
        {%- if ": " in right -%}{{ right.split(": ", 1)[1] | trim }}{%- else -%}{{ right | trim }}{%- endif -%}
    {%- endif -%}
{%- endmacro -%}

{#-- Combined color + liner --#}
{%- macro color_display(color, item) -%}
    {%- set liner = parse_liner(item) | trim -%}
    {%- if color and liner -%}{{ color }} WITH {{ liner }}
    {%- elif color -%}{{ color }}
    {%- else -%}—{%- endif -%}
{%- endmacro -%}

<div style="font-family: Arial, sans-serif; font-size: 10px; color: #000; line-height: 1.5; text-transform: uppercase;">

  <!-- LOGO -->
  <div style="margin-bottom: 6px; margin-left: 0px; margin-right: -8px; width: 100%">
      <img src="/files/Instabiz_LH_v2.png"
           style="width: 100%; height: 100%; display: block; object-fit: cover;" />
  </div>
    <div style="border-top: 1px solid #000; margin: 6px 0;"></div>

    <!-- TWO-COLUMN: BANK DETAILS (LEFT 33%) | WAREHOUSE INFO (RIGHT 66%) -->
    <table style="width: 100%; border-collapse: collapse; font-size: 9px; margin-bottom: 4px;">
        <tr>
            <td style="width: 33%; vertical-align: top; padding-right: 10px;">
                <strong style="color: #c0392b; font-weight: bold;">BANK DETAILS</strong><br>
                <strong>NAME :</strong> INSTABIZ SOLUTIONS INDIA PVT LTD<br>
                <strong>BANK NAME :</strong> HDFC BANK<br>
                <strong>BRANCH :</strong> MOHD ALI ROAD<br>
                <strong>A/C NO :</strong> 50200023672503<br>
                <strong>IFSC CODE :</strong> HDFC0000627
            </td>
            <td style="width: 67%; vertical-align: top; padding-left: 10px; border-left: 1px solid #ccc;">
                <strong style="color: #c0392b; font-weight: bold;">GST</strong> : {{ display_gstin }}<br>
                <strong style="font-weight: bold;">ADDRESS</strong> : {{ wh_abbr }}
            </td>
        </tr>
    </table>

    <!-- SEPARATOR -->
    <div style="border-top: 1px solid #000; margin: 4px 0;"></div>

    <!-- 3-COLUMN: WEBSITE | PHONE | EMAIL -->
    <table style="width: 100%; border-collapse: collapse; font-size: 9px; margin-bottom: 12px;">
        <tr>
            <td style="width: 33%; text-align: left; padding: 2px 0 !important;">
                <strong>WEBSITE :</strong> <span style="text-transform: lowercase !important;">www.instabizsolutions.com</span>
            </td>
            <td style="width: 34%; text-align: center; padding: 2px 0 !important; border-left: 1px solid #ccc;">
                <strong>PHONE :</strong> {{ wh_phone }}
            </td>
            <td style="width: 33%; text-align: right; padding: 2px 0 !important; border-left: 1px solid #ccc;">
                <strong>EMAIL :</strong> <span style="text-transform: lowercase !important;">{{ wh_email }}</span>
            </td>
        </tr>
    </table>

    <!-- MAIN BORDERED BOX -->
    <div style="border: 1.5px solid #000;">

        <!-- TITLE -->
        <div style="text-align: center; padding: 8px 0; border-bottom: 1.5px solid #000;
                    font-size: 13px; font-weight: bold; letter-spacing: 1px;">
            - PROFORMA INVOICE -
        </div>

        <!-- HEADER INFO: 3-column flat table, no vertical dividers -->
        <table style="width: 100%; border-collapse: collapse; font-size: 9px;
                      border-bottom: 1.5px solid #000;">
            <tr>
                <!-- Left: Customer -->
                <td style="width: 35%; padding: 10px 14px; vertical-align: top; line-height: 1.8;">
                    <div><strong>CUSTOMER NAME :</strong> {{ doc.customer_name or "" }}</div>
                    {% if is_international %}
                    <div><strong>COUNTRY :</strong> {{ customer_country or "—" }}</div>
                    {% else %}
                    <div>
                        <strong>GST NO :</strong>
                        {%- set gstin = frappe.db.get_value("Customer", doc.party_name or doc.customer, "gstin") -%}
                        {{ gstin or "—" }}
                    </div>
                    {% endif %}
                    <div><strong>ADDRESS :</strong> {{ address_html }}</div>
                    {% if contact_display %}
                    <div><strong>CONTACT NO :</strong> {{ contact_display }}</div>
                    {% endif %}
                </td>

                <!-- Middle: Sales info -->
                <td style="width: 30%; padding: 10px 14px; vertical-align: top; line-height: 1.8; border-left: 1px solid #ccc;">
                    <div><strong>SALES PERSON :</strong> {{ sales_person_name }}</div>
                    <div><strong>LOCATION :</strong> {{ doc.custom_location or "—" }}</div>
                    <div><strong>PI NO :</strong> {{ doc.name }}</div>
                    <div><strong>DATE :</strong> {{ frappe.format(doc.transaction_date, {"fieldtype": "Date"}) }}</div>
                </td>

                <!-- Right: Order procedure -->
                <td style="width: 35%; padding: 10px 14px; vertical-align: top; line-height: 1.8; border-left: 1px solid #ccc;">
                    <div style="font-weight: bold; color: #c0392b; margin-bottom: 3px;">ORDER PROCEDURE</div>
                    <div><strong>TRANSPORT :</strong> {{ doc.get("custom_transport") or "—" }}</div>
                    <div><strong>BOOKING FOR :</strong> {{ doc.get("booking_for") or "—" }}</div>
                    <div><strong>Reference PO:</strong> {{ doc.get("custom_reference_po") or "—"}}</div>
                </td>
            </tr>
        </table>

        <!-- ITEMS TABLE -->
        <table style="width: 100%; border-collapse: collapse; font-size: 8px; table-layout: fixed;">
            <colgroup>
                <col style="width: 3%;">   <!-- # -->
                <col style="width: 15%;">  <!-- ITEM -->
                <col style="width: 5%;">   <!-- THICKNESS -->
                <col style="width: 9%;">   <!-- COLOR -->
                <col style="width: 5%;">   <!-- WIDTH MM -->
                <col style="width: 5%;">   <!-- LENGTH MTR -->
                <col style="width: 5%;">   <!-- QTY/PKG -->
                <col style="width: 5%;">   <!-- TOTAL PKG -->
                <col style="width: 7%;">   <!-- PRICE -->
                <col style="width: 6%;">   <!-- RATE FOR -->
                <col style="width: 9%;">   <!-- VALUE -->
                <col style="width: 8%;">   <!-- TAX -->
                <col style="width: 9%;">   <!-- TOTAL -->
            </colgroup>
            <thead>
                <tr style="border-bottom: 1.5px solid #000; border-top: 1px solid #000;
                           background: #f2f2f2; font-weight: bold; text-align: center;">
                    <th style="padding: 3px 2px; border-right: 1px solid #ccc; vertical-align: middle; overflow: hidden; word-break: break-word;">#</th>
                    <th style="padding: 3px 2px; border-right: 1px solid #ccc; text-align: left; vertical-align: middle; overflow: hidden; word-break: break-word;">ITEM</th>
                    <th style="padding: 3px 2px; border-right: 1px solid #ccc; vertical-align: middle; overflow: hidden; word-break: break-word;">THICKNESS</th>
                    <th style="padding: 3px 2px; border-right: 1px solid #ccc; vertical-align: middle; overflow: hidden; word-break: break-word;">COLOR</th>
                    <th style="padding: 3px 2px; border-right: 1px solid #ccc; vertical-align: middle; overflow: hidden; word-break: break-word;">WIDTH<br>(MM)</th>
                    <th style="padding: 3px 2px; border-right: 1px solid #ccc; vertical-align: middle; overflow: hidden; word-break: break-word;">LENGTH<br>(MTR)</th>
                    <th style="padding: 3px 2px; border-right: 1px solid #ccc; vertical-align: middle; overflow: hidden; word-break: break-word;">QTY /<br>PKG</th>
                    <th style="padding: 3px 2px; border-right: 1px solid #ccc; vertical-align: middle; overflow: hidden; word-break: break-word;">TOTAL<br>PKG</th>
                    <th style="padding: 3px 2px; border-right: 1px solid #ccc; vertical-align: middle; overflow: hidden; word-break: break-word;">PRICE</th>
                    <th style="padding: 3px 2px; border-right: 1px solid #ccc; vertical-align: middle; overflow: hidden; word-break: break-word;">RATE<br>FOR</th>
                    <th style="padding: 3px 2px; border-right: 1px solid #ccc; text-align: right; vertical-align: middle; overflow: hidden; word-break: break-word;">VALUE</th>
                    <th style="padding: 3px 2px; border-right: 1px solid #ccc; text-align: right; vertical-align: middle; overflow: hidden; word-break: break-word;">{% if is_international %}TAX{% else %}GST<br>(18%){% endif %}</th>
                    <th style="padding: 3px 2px; text-align: right; vertical-align: middle; overflow: hidden; word-break: break-word;">TOTAL</th>
                </tr>
            </thead>
            <tbody>
                {% if doc.items %}
                {% for item in doc.items %}
                {%- if is_international -%}
                    {%- set gst_amount = 0 -%}
                {%- else -%}
                    {%- set gst_amount = (item.amount or 0) * 0.18 -%}
                {%- endif -%}
                <tr style="border-bottom: 1px solid #ccc;
                           {% if loop.index is odd %}background: #fff;{% else %}background: #f5f5f5;{% endif %}">

                    <td style="padding: 3px 2px; border-right: 1px solid #ccc;
                               text-align: center; vertical-align: top;">{{ loop.index }}.</td>

                    <td style="padding: 2px 2px; border-right: 1px solid #ccc;
                               word-wrap: break-word; vertical-align: top;">
                        <div style="font-weight: bold;">
                        {% if item.get("item_name") and item.item_name != item.item_code %}
                            {{ item.item_name }} - {{ item.item_code }}
                        {% else %}
                            {{ item.item_code or "" }}
                        {% endif %}
                        </div>
                        {% if item.get("custom_description") %}
                        <div style="font-size: 7px; color: #555; margin-top: 2px;">{{ item.custom_description }}</div>
                        {% endif %}
                    </td>

                    <td style="padding: 3px 2px; border-right: 1px solid #ccc;
                               text-align: center; vertical-align: top;">
                        {{ item.get('custom_thickness') or "—" }}
                    </td>

                    <td style="padding: 3px 2px; border-right: 1px solid #ccc;
                               text-align: center; word-wrap: break-word; vertical-align: top;">
                        {{ color_display(item.get("color") or "", item) }}
                    </td>

                    <td style="padding: 3px 2px; border-right: 1px solid #ccc;
                               text-align: center; vertical-align: top;">
                        {{ fmt_num(item.get("width_mm") or 0) if item.get("width_mm") else "—" }}
                    </td>

                    <td style="padding: 3px 2px; border-right: 1px solid #ccc;
                               text-align: center; vertical-align: top;">
                        {{ fmt_num(item.get("length_mtr") or 0) if item.get("length_mtr") else "—" }}
                    </td>

                    <td style="padding: 3px 2px; border-right: 1px solid #ccc;
                               text-align: center; vertical-align: top;">
                        {{ fmt_qty(item.get("qty_pkg") or 0) if item.get("qty_pkg") else "—" }}
                    </td>

                    <td style="padding: 3px 2px; border-right: 1px solid #ccc;
                               text-align: center; vertical-align: top;">
                        {{ fmt_qty(item.get("total_pkg") or 0) if item.get("total_pkg") else "—" }}
                    </td>

                    <td style="padding: 3px 2px; border-right: 1px solid #ccc;
                               text-align: center; vertical-align: top;">
                        {{ "%.2f"|format(item.rate or 0) }}
                    </td>

                    <td style="padding: 3px 2px; border-right: 1px solid #ccc;
                               text-align: center; vertical-align: top;">
                        {{ "SQM" if item.uom == "SQMT" else (item.uom or "") }}
                    </td>

                    <td style="padding: 3px 2px; border-right: 1px solid #ccc;
                               text-align: right; vertical-align: top;">
                        {{ "%.2f"|format(item.amount or 0) }}
                    </td>

                    <td style="padding: 3px 2px; border-right: 1px solid #ccc;
                               text-align: right; vertical-align: top;">
                        {{ "%.2f"|format(gst_amount) }}
                    </td>

                    <td style="padding: 3px 2px; text-align: right; vertical-align: top;">
                        {{ "%.2f"|format((item.amount or 0) + gst_amount) }}
                    </td>

                </tr>
                {% endfor %}
                {% endif %}
            </tbody>
        </table>

        <!-- TOTALS -->
        <div style="display: flex; border-top: 1.5px solid #000;">
            <div style="width: 55%;"></div>
            <div style="width: 45%; border-left: 1.5px solid #000;">
                <table style="width: 100%; border-collapse: collapse; font-size: 9px;">
                    <tr style="border-bottom: 1px solid #ddd;">
                        <td style="padding: 5px 10px; color: #555; font-style: italic;">
                            TOTAL AMOUNT BEFORE TAX ({{ display_currency }}):
                        </td>
                        <td style="padding: 5px 10px; text-align: right; font-weight: bold;">
                            {{ "%.2f"|format(doc.net_total or 0) }}
                        </td>
                    </tr>
                    {% if is_international %}
                    <tr style="border-bottom: 1px solid #ddd;">
                        <td style="padding: 5px 10px; color: #555; font-style: italic;">
                            TAX (EXPORT / ZERO-RATED):
                        </td>
                        <td style="padding: 5px 10px; text-align: right;">
                            0.00
                        </td>
                    </tr>
                    {% else %}
                     {% for tax in doc.taxes %}
                    <tr style="border-bottom: 1px solid #ddd;">
                        <td style="padding: 5px 10px; color: #555; font-style: italic;">
                            {{ tax.description or "GST" }}{% if tax.rate %} ({{ tax.rate }}%):{% endif %}
                        </td>
                        <td style="padding: 5px 10px; text-align: right;">
                            {{ "%.2f"|format(tax.tax_amount or 0) }}
                        </td>
                    </tr>
                    {% endfor %}
                    {% endif %}
                    <tr style="background: #f5f5f5;">
                        <td style="padding: 7px 10px; font-weight: bold; font-size: 10px;">
                            NET AMOUNT ({{ display_currency }}):
                        </td>
                        <td style="padding: 7px 10px; text-align: right;
                                   font-weight: bold; font-size: 11px;">
                            {{ "%.2f"|format(doc.rounded_total or doc.grand_total or 0) }}
                        </td>
                    </tr>
                </table>
            </div>
        </div>

        <!-- AMOUNT IN WORDS -->
        {% if doc.in_words %}
        <div style="padding: 6px 10px; border-top: 1.5px solid #000; font-size: 9px;">
            <strong>AMOUNT (IN WORDS) :</strong> {{ doc.in_words | upper }}
        </div>
        {% endif %}

    </div>

    <!-- TERMS -->
    {% if doc.terms %}
    <div style="margin-top: 14px;">
        <div style="font-size: 10px; font-weight: bold; color: #c0392b; margin-bottom: 6px;">
            GENERAL TERMS AND CONDITIONS
        </div>
        <div style="font-size: 9px; color: #333; line-height: 1.8;">{{ doc.terms }}</div>
    </div>
    {% endif %}

</div>
